@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_get_org_summary_success(api_client, config_test_data, scenario_case):
    """
    Test successful retrieval of org summary metrics with valid credentials.
    """
    org_slug = scenario_case.get("org-slug", config_test_data['org-slug'])
    reporting_window = scenario_case.get("reporting-window", "last-90-days")
    project_names = scenario_case.get("project-names", {})

    # Construct query parameters
    params = {"reporting-window": reporting_window}
    if project_names:
        for key, value in project_names.items():
            params[f"project-names"] = value

    # Make the API request
